// obs_norm: raw observation divided by POLICY_OBS_SCALE (same order as BalanceRobotEnv._get_obs)
// action:   wheel torques in [-1, 1], multiply by POLICY_MAX_TORQUE for Nm
static inline void policy_forward(const float obs_norm[POLICY_OBS_DIM], float action[POLICY_ACT_DIM]) {
    static float buf_a[128], buf_b[128];
    const float *in = obs_norm;
    float *out = buf_a;
    for (int o = 0; o < 128; o++) {
        float s = B0[o];
        for (int k = 0; k < 9; k++) s += W0[o * 9 + k] * in[k];
        out[o] = tanhf(s);
    }
    in = out; out = (out == buf_a) ? buf_b : buf_a;
    for (int o = 0; o < 128; o++) {
        float s = B1[o];
        for (int k = 0; k < 128; k++) s += W1[o * 128 + k] * in[k];
        out[o] = tanhf(s);
    }
    in = out; out = (out == buf_a) ? buf_b : buf_a;
    for (int o = 0; o < 2; o++) {
        float s = B2[o];
        for (int k = 0; k < 128; k++) s += W2[o * 128 + k] * in[k];
        action[o] = s < -1.0f ? -1.0f : (s > 1.0f ? 1.0f : s);
    }
}
